import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/ko/db-import-objects.png",l="/relio/shots/ko/db-compare-sql.png",u=JSON.parse('{"title":"DB에서 가져오기·DB에 반영","description":"","frontmatter":{},"headers":[],"relativePath":"quick/database.md","filePath":"quick/database.md"}'),s={name:"quick/database.md"};function n(c,a,d,D,b,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="db에서-가져오기·db에-반영" tabindex="-1">DB에서 가져오기·DB에 반영 <a class="header-anchor" href="#db에서-가져오기·db에-반영" aria-label="Permalink to &quot;DB에서 가져오기·DB에 반영&quot;">​</a></h1><p>이미 있는 DB의 구조를 모델로 가져오고, 모델을 DB에 반영합니다.</p><h2 id="db에서-가져오기" tabindex="-1">DB에서 가져오기 <a class="header-anchor" href="#db에서-가져오기" aria-label="Permalink to &quot;DB에서 가져오기&quot;">​</a></h2><ol><li>파일 › 가져오기 › DB에서를 엽니다.</li><li>접속 정보를 넣고 접속합니다. PostgreSQL·MySQL·MariaDB·SQL Server·SQLite는 드라이버가 앱에 들어 있어 따로 설치할 것이 없습니다.</li><li>가져올 스키마를 고릅니다.</li><li>테이블·뷰·시퀀스·트리거를 골라 문서에 넣습니다. 가져오기 전체가 <kbd>Ctrl</kbd>+<kbd>Z</kbd> 한 번으로 돌아갑니다.</li></ol><figure class="shot" data-scene="db-import-objects"><img src="'+r+'" alt="DB에서 가져오기 — 가져올 객체를 고르는 단계" loading="lazy"><figcaption>DB에서 가져오기 — 가져올 객체를 고르는 단계</figcaption></figure><h2 id="db에-반영" tabindex="-1">DB에 반영 <a class="header-anchor" href="#db에-반영" aria-label="Permalink to &quot;DB에 반영&quot;">​</a></h2><ul><li><strong>처음 만들 때</strong> — 파일 › DB로 내보내기…(도구 모음에도 있음). 실행할 SQL을 먼저 보여 주고, 지원하는 DB에서는 한 트랜잭션으로 실행해 중간에 실패하면 되돌립니다.</li><li><strong>바뀐 것만 반영할 때</strong> — 모델과 DB 구조의 차이로 변경 SQL(ALTER)을 만듭니다. <ol><li>새 다이어그램에서 DB에서 가져오기로 지금 DB 구조를 가져와 파일로 저장합니다(예: <code>db-now.erm</code>).</li><li>반영할 모델을 열고 파일 › 비교·병합 › 다른 파일과 비교…에서 그 파일을 고릅니다.</li><li>비교 화면의 내보내기 ▾ › 변경 SQL 만들기로 SQL을 만듭니다(PostgreSQL·MySQL·MariaDB·SQL Server·Oracle).</li><li>위험한 변경 경고와 &quot;수동 처리 필요&quot; 목록을 확인한 뒤 DB 도구에서 직접 실행합니다. Relio는 이 SQL을 실행하지 않습니다.</li></ol></li></ul><figure class="shot" data-scene="db-compare-sql"><img src="'+l+'" alt="비교 화면에서 변경 SQL을 만든 모습" loading="lazy"><figcaption>비교 화면에서 변경 SQL을 만든 모습</figcaption></figure><div class="warning custom-block"><p class="custom-block-title">주의</p><p>실제 DB에 실행하기 전에 늘 SQL을 읽어 보고, 운영 DB라면 백업부터 하세요.</p></div><p>Oracle은 Oracle Instant Client 폴더를, DB2·Informix·MS Access는 ODBC 드라이버를 먼저 준비합니다. H2·HSQLDB는 직접 접속할 수 없으니 DDL 파일로 내보내 실행하세요. DB 암호는 기본으로 Windows 자격 증명 관리자에 저장합니다.</p><p><strong>자세히</strong> → <a href="/relio/features/database">DB 연동</a> · <a href="/relio/features/git#변경-sql-만들기">Git과 합치기 › 변경 SQL 만들기</a> · <a href="/relio/features/troubleshooting#자주-만나는-문제">도움말과 문제 해결</a></p>',11)])])}const f=e(s,[["render",n]]);export{u as __pageData,f as default};
